package LeanBridgeBuild;
use strict;
use warnings;
use Config;
use Digest::SHA qw(sha256_hex);
use JSON::PP;
use File::Basename qw(dirname basename);
use File::Path qw(make_path);
use File::Copy qw(copy);
use File::Spec;
use Cwd qw(abs_path);
use ExtUtils::MakeMaker 6.64;
use lib 'inc';
use LeanBridge::Runtime::Platform;

# Packaged with each distribution; installation never invokes Lean, Lake or Node.
sub read_bytes {
  my ($path) = @_;
  open my $file, '<:raw', $path or die "Cannot read $path: $!\n";
  local $/; return <$file>;
}
sub read_json { return JSON::PP->new->decode(read_bytes($_[0])); }
sub write_json {
  my ($path, $value) = @_;
  open my $file, '>:raw', $path or die "Cannot write $path: $!\n";
  print {$file} JSON::PP->new->canonical->encode($value), "\n";
  close $file or die "Cannot close $path: $!\n";
}
sub abi { return LeanBridge::Runtime::Platform::abi(); }
sub abi_key { return LeanBridge::Runtime::Platform::abi_key(); }
sub platform { return LeanBridge::Runtime::Platform::platform(@_); }
sub checked_path {
  my ($path) = @_;
  die "Unsafe package path\n" if !defined($path) || $path !~ m{\A[A-Za-z0-9_.+/-]+\z}
    || $path =~ m{(?:\A|/)\.\.(?:/|\z)} || $path =~ m{\A/};
  my $partial = '';
  for my $part (split m{/}, $path) {
    die "Unsafe package path\n" if $part eq '' || $part eq '.' || $part eq '..';
    $partial = length($partial) ? "$partial/$part" : $part;
    die "Symlink in package payload: $partial\n" if -l $partial;
  }
  return $path;
}
sub verify {
  my ($manifest) = @_;
  for my $path (sort keys %{$manifest->{files}}) {
    checked_path($path);
    die "Corrupt package artifact: $path\n" unless sha256_hex(read_bytes($path)) eq $manifest->{files}{$path};
  }
}
sub _owned_values_before_callback_results {
  my ($manifest) = @_;
  return unless exists $manifest->{ownedValues};
  my $owned = $manifest->{ownedValues};
  die "Invalid owned Perl package contract\n" unless ref($owned) eq 'HASH'
    && $manifest->{module} ne 'LeanBridge::Runtime'
    && ($owned->{schemaVersion} == 1 || $owned->{schemaVersion} == 2 || $owned->{schemaVersion} == 3 || $owned->{schemaVersion} == 4)
    && $owned->{prefix} =~ /\A[A-Za-z_][A-Za-z0-9_]*\z/
    && $owned->{gmpLibrary} eq 'libgmp-lean-bridge.so.10'
    && $owned->{componentLibrary} =~ /\A[A-Za-z0-9_][A-Za-z0-9_.+-]*\.so\z/;
  my $model = read_json('model.json');
  my $anchored = $owned->{schemaVersion} == 3 || $model->{schemaVersion} == 9
    || exists($owned->{resultAnchors}) || exists($model->{ownedGraph}{resultAnchors});
  my $receivers = $owned->{schemaVersion} == 4 || $model->{schemaVersion} == 10
    || exists($owned->{receiverExports}) || exists($model->{ownedGraph}{receiverExports});
  if ($receivers || $anchored || $owned->{schemaVersion} == 2 || $model->{schemaVersion} == 8) {
    my $binding = read_json('binding-manifest.json');
    my $native = $model->{ownedGraph}{inputTransfers};
    my $moves = $owned->{inputTransfers};
    my $json = JSON::PP->new->canonical;
    die "Invalid owned Perl lifetime contract\n"
      unless $owned->{schemaVersion} == ($receivers ? 4 : $anchored ? 3 : 2)
        && $model->{schemaVersion} == ($receivers ? 10 : $anchored ? 9 : 8)
        && $binding->{schemaVersion} == ($receivers ? 4 : $anchored ? 3 : 2)
        && $json->encode($binding->{owned}) eq $json->encode($owned)
        && $owned->{bindingIrSha256} eq $model->{bindingIrSha256};
    if ((!$anchored && !$receivers) || defined($native) || defined($moves)) {
      die "Invalid owned Perl input-transfer contract\n" unless ref($native) eq 'HASH' && ref($moves) eq 'HASH';
      my %expected = (%$native, arguments => ($anchored || $receivers) ? 'whole-values' : 'ordinary-values',
        aliases => ($anchored || $receivers) ? 'shared-owner' : 'shared-lease',
        borrowedInputs => 'reject', independentRetains => 'preserved');
      die "Owned Perl input transfers differ from the native model\n"
        unless $json->encode($moves) eq $json->encode(\%expected);
    }
    if ($anchored) {
      my $anchors = $model->{ownedGraph}{resultAnchors};
      die "Invalid owned Perl borrowed-result contract\n"
        unless ref($anchors) eq 'HASH' && ref($owned->{resultAnchors}) eq 'HASH';
      my %expected = (%$anchors, arguments => 'whole-values', results => 'checked-whole-values',
        emptyValues => 'owner-scoped', independentRetains => 'preserved', identityEquality => 'native-identity');
      die "Owned Perl result anchors differ from the native model\n"
        unless $json->encode($owned->{resultAnchors}) eq $json->encode(\%expected);
    }
    if ($receivers) {
      my $members = $model->{ownedGraph}{receiverExports};
      die "Invalid owned Perl receiver contract\n"
        unless ref($members) eq 'HASH' && ref($owned->{receiverExports}) eq 'HASH';
      my %expected = (%$members, values => 'checked-whole-result', members => 'snake-case',
        properties => 'read-only-zero-argument-methods', owners => 'nominal-whole-values',
        consumingReceivers => 'original-owner-handoff');
      die "Owned Perl receivers differ from the native model\n"
        unless $json->encode($owned->{receiverExports}) eq $json->encode(\%expected);
    }
  }
  return $owned;
}
sub compile_xs {
  my ($manifest, $directory) = @_;
  require ExtUtils::ParseXS;
  require ExtUtils::CBuilder;
  die "Perl headers are unavailable; install the development package for this Perl\n"
    unless -f "$Config{archlib}/CORE/perl.h";
  make_path($directory);
  my $stem = $manifest->{module}; $stem =~ s/.*:://;
  my $c = "$directory/$stem.c";
  ExtUtils::ParseXS::process_file(filename => checked_path($manifest->{xs}), output => $c, prototypes => 0);
  my @include = ('.', $manifest->{include});
  my $runtime_root;
  if ($manifest->{module} ne 'LeanBridge::Runtime') {
    require LeanBridge::Runtime;
    die "Incompatible shared Lean runtime package version\n" unless $LeanBridge::Runtime::VERSION eq $manifest->{runtimeVersion};
    die "Incompatible shared Lean runtime\n" unless LeanBridge::Runtime::_identity() eq $manifest->{runtimeIdentity};
    my $root = $INC{'LeanBridge/Runtime.pm'}; $root =~ s/\.pm\z//;
    $runtime_root = $root;
    push @include, "$root/include";
  }
  my @link_flags = ('-Wl,--build-id=none');
  if (my $owned = owned_values($manifest)) {
    push @include, map { checked_path($_) } qw(owned/include owned/internal owned/gmp/include);
    my $relative = $manifest->{module}; $relative =~ s{::}{/}g;
    my $native = checked_path("lib/$relative/native");
    # Order is part of the ownership ABI: the C adapter must use private GMP.
    push @link_flags, '-L', $native, '-L', "$runtime_root/native", '-Wl,--no-as-needed',
      "-l:$owned->{gmpLibrary}", "-l:$owned->{componentLibrary}", '-llean_bridge_native', '-lleanshared';
  }
  # Keep root identities for both compiler diagnostics and the build receipt.
  my @root_mappings = ([abs_path('.'), '\${DISTRIBUTION}', '/lean-bridge/distribution'],
    [abs_path("$Config{archlib}/CORE"), '\${PERL_CORE}', '/perl/core']);
  push @root_mappings, [abs_path($runtime_root), '\${LEAN_BRIDGE_RUNTIME}', '/lean-bridge/runtime']
    if defined $runtime_root;
  # CBuilder appends Config's optimize flags after extra_compiler_flags. A distro
  # -g there would restore debug paths and make relocated archives differ.
  my $builder = LeanBridgeBuild::Compiler->new(quiet => 0, config => { optimize => '-O2 -g0' });
  die "C compiler unavailable; install one or select a compatible prebuilt XS\n" unless $builder->have_compiler;
  $builder->{lean_bridge_commands} = [];
  my @flags = qw(-O2 -g0 -fvisibility=default);
  # Lean's inline assertions embed __FILE__ even with debug information disabled.
  # Their runtime-header location must not expose a producer/installer directory.
  push @flags, map { "-ffile-prefix-map=$_->[0]=$_->[2]" } @root_mappings
    if owned_values($manifest);
  my $object = $builder->compile(source => $c, include_dirs => \@include,
    extra_compiler_flags => \@flags);
  my $library = $builder->link(objects => $object, module_name => $manifest->{module},
    lib_file => "$directory/$stem.$Config{dlext}", extra_linker_flags => \@link_flags);
  # Paths vary between build roots. Keep exact flags and portable root tokens.
  my %roots = map { $_->[0] => $_->[1] } @root_mappings;
  my $flags = join ' ', @flags;
  for my $root (sort { length($b) <=> length($a) } keys %roots) { $flags =~ s/\Q$root\E/$roots{$root}/g; }
  my @commands = map { [map {
    my $argument = $_;
    for my $root (sort { length($b) <=> length($a) } keys %roots) { $argument =~ s/\Q$root\E/$roots{$root}/g; }
    $argument;
  } @$_] } @{$builder->{lean_bridge_commands}};
  my $receipt = { schemaVersion => 1, operation => 'generated-xs-only', abi => abi(),
    sourceSha256 => $manifest->{files}{$manifest->{xs}}, compiler => $Config{cc},
    compilerFlags => $Config{ccflags}, extraCompilerFlags => $flags,
    linker => $Config{ld}, linkerFlags => $Config{lddlflags}, commands => \@commands,
    generatedCSha256 => sha256_hex(read_bytes($c)), runtimeIdentity => $manifest->{runtimeIdentity},
    outputSha256 => sha256_hex(read_bytes($library)) };
  write_json("$directory/receipt.json", $receipt);
  verify($manifest);
  return ($library, $receipt);
}
sub seal_owned_loader {
  my ($manifest, $relative, $receipt) = @_;
  return unless owned_values($manifest);
  my $original = "lib/$relative.pm";
  my $source = read_bytes($original);
  my $marker = '__LEAN_BRIDGE_OWNED_XS_SHA256__';
  my $hash = $receipt->{outputSha256};
  die "Invalid installed XS identity\n" unless defined($hash) && $hash =~ /\A[0-9a-f]{64}\z/;
  my $count = ($source =~ s/\Q$marker\E/$hash/g);
  die "Owned Perl loader has no unique XS seal\n" unless $count == 1;
  # Keep the verified distribution sources unchanged, including on reconfigure.
  # A complete private data copy also supports the mandatory pre-install load.
  for my $path ((sort keys %{$manifest->{files}}), "lib/$relative/install-receipt.json") {
    next unless index($path, "lib/$relative/") == 0;
    my $target = "_owned-install/$path";
    make_path(dirname($target)); copy($path, $target) or die "Cannot stage owned loader data: $!\n";
  }
  my $target = "_owned-install/$original";
  make_path(dirname($target));
  open my $file, '>:raw', $target or die "Cannot stage owned Perl loader: $!\n";
  print {$file} $source;
  close $file or die "Cannot finish owned Perl loader: $!\n";
  return $target;
}
sub configure {
  my $manifest = read_json('lean-bridge-package.json');
  die "Unsupported Perl package format\n" unless $manifest->{schemaVersion} == 1;
  verify($manifest);
  platform($manifest->{glibcMinimumVersion});
  if ($manifest->{module} eq 'LeanBridge::Runtime') {
    die "Incompatible Perl binding runtime identity\n"
      unless sha256_hex(read_bytes('lib/LeanBridge/Runtime/binding.json')) eq $manifest->{runtimeIdentity};
  } else {
    require LeanBridge::Runtime;
    die "Incompatible shared Lean runtime package version\n" unless $LeanBridge::Runtime::VERSION eq $manifest->{runtimeVersion};
    die "Incompatible shared Lean runtime\n" unless LeanBridge::Runtime::_identity() eq $manifest->{runtimeIdentity};
  }
  my $mode = $ENV{LEAN_BRIDGE_PERL_INSTALL_MODE} // 'auto';
  die "LEAN_BRIDGE_PERL_INSTALL_MODE must be auto, prebuilt-only or build-xs\n"
    unless $mode =~ /\A(?:auto|prebuilt-only|build-xs)\z/;
  my $key = abi_key();
  my ($prebuilt) = grep { $_->{abiKey} eq $key } @{$manifest->{prebuilt}};
  my ($library, $receipt);
  if ($mode ne 'build-xs' && $prebuilt) {
    die "Corrupt prebuilt ABI fingerprint\n" unless sha256_hex(JSON::PP->new->canonical->encode($prebuilt->{abi})) eq $prebuilt->{abiKey};
    $library = checked_path($prebuilt->{path});
    die "Prebuilt XS is not covered by the artifact inventory\n" unless exists $manifest->{files}{$library};
    $receipt = { schemaVersion => 1, operation => 'prebuilt-xs', abi => abi(), outputSha256 => $manifest->{files}{$library} };
  } else {
    die "No compatible prebuilt XS for this Perl; use auto or build-xs with matching headers and a C compiler\n" if $mode eq 'prebuilt-only';
    ($library, $receipt) = compile_xs($manifest, '_xs-build');
  }
  my $relative = $manifest->{module}; $relative =~ s{::}{/}g;
  my $stem = basename($relative);
  my $binary = "lib/auto/$relative/$stem.$Config{dlext}";
  make_path(dirname($binary)); copy($library, $binary) or die "Cannot stage XS: $!\n";
  my $receipt_path = "lib/$relative/install-receipt.json";
  make_path(dirname($receipt_path)); write_json($receipt_path, $receipt);
  my $sealed_loader = seal_owned_loader($manifest, $relative, $receipt);
  my %pm;
  for my $path (sort keys %{$manifest->{files}}) {
    next unless $path =~ m{\Alib/};
    (my $target = $path) =~ s{\Alib/}{\$(INST_LIB)/};
    $pm{$path} = $target;
  }
  $pm{$binary} = "\$(INST_ARCHLIB)/auto/$relative/$stem.$Config{dlext}";
  $pm{$receipt_path} = "\$(INST_LIB)/$relative/install-receipt.json";
  if (defined $sealed_loader) {
    delete $pm{"lib/$relative.pm"};
    $pm{$sealed_loader} = "\$(INST_LIB)/$relative.pm";
  }
  # Loading the chosen XS is mandatory, including in prebuilt-only mode.
  # Corrupt or ABI-incompatible binaries fail here. They never trigger fallback.
  system($^X, (defined($sealed_loader) ? ('-I_owned-install/lib') : ()),
    '-Ilib', '-M' . $manifest->{module}, '-e', '1') == 0
    or die "Installed XS compatibility check failed\n";
  my $metadata = read_json('META.json');
  WriteMakefile(NAME => $manifest->{module}, VERSION => $manifest->{version},
    ABSTRACT => $metadata->{abstract}, AUTHOR => join(', ', @{$metadata->{author}}),
    LICENSE => $metadata->{license}[0], MIN_PERL_VERSION => '5.036',
    META_MERGE => { 'meta-spec' => { version => 2 },
      (exists $metadata->{x_spdx_expression} ? (x_spdx_expression => $metadata->{x_spdx_expression}) : ()),
      (exists $metadata->{resources} ? (resources => $metadata->{resources}) : ()) },
    CONFIGURE_REQUIRES => $metadata->{prereqs}{configure}{requires},
    PREREQ_PM => { 'Math::BigInt' => 0, 'JSON::PP' => 0, 'Digest::SHA' => 0,
      ($manifest->{module} eq 'LeanBridge::Runtime' ? () : ('LeanBridge::Runtime' => '== ' . $manifest->{runtimeVersion})) },
    PM => \%pm, XS => {}, C => [], OBJECT => '', NO_META => 1,
    clean => { FILES => '_xs-build' });
}

package LeanBridgeBuild::Compiler;
our @ISA = ('ExtUtils::CBuilder');
sub do_system {
  my ($self, @command) = @_;
  push @{$self->{lean_bridge_commands}}, [@command];
  return $self->SUPER::do_system(@command);
}
1;

package LeanBridgeBuild;
use strict;
use warnings;

# This template is appended only to owned-v5 component installers. Legacy and
# runtime distributions keep Build.pm unchanged, including its exact version.
sub owned_values {
  my ($manifest) = @_;
  my $fail = sub { die "Invalid owned Perl callback-result contract: $_[0]\n" };
  my $json = JSON::PP->new->canonical;
  my $same = sub { $json->encode($_[0]) eq $json->encode($_[1]) };
  my $version = sub { defined($_[0]) && !ref($_[0]) && $json->encode($_[0]) eq "$_[1]" };
  my $digest = sub { defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[0-9a-f]{64}\z/ };
  my $exact = sub {
    my ($value, @keys) = @_;
    $fail->('unexpected ownership fields') unless ref($value) eq 'HASH'
      && $same->([sort keys %$value], [sort @keys]);
  };
  my $model = read_json('model.json');
  my $binding = read_json('binding-manifest.json');
  my $receipt = read_json('native-component.json');
  my $ir = read_json('binding-ir.json');
  $fail->('invalid witness documents') unless ref($manifest) eq 'HASH' && ref($model) eq 'HASH'
    && ref($binding) eq 'HASH' && ref($receipt) eq 'HASH' && ref($ir) eq 'HASH';
  my $owned = $manifest->{ownedValues};
  my $graph = $model->{ownedGraph};
  $fail->('unsupported v5 schema') unless ref($manifest) eq 'HASH'
    && $version->($manifest->{schemaVersion}, 1)
    && defined($manifest->{module}) && $manifest->{module} =~ /\ALeanBridge(?:::[A-Za-z][A-Za-z0-9_]*)+\z/
    && $manifest->{module} !~ /\ALeanBridge::Runtime(?:::|\z)/
    && ref($owned) eq 'HASH' && $version->($owned->{schemaVersion}, 5)
    && ref($model) eq 'HASH' && $version->($model->{schemaVersion}, 11)
    && ref($graph) eq 'HASH' && $version->($graph->{schemaVersion}, 6)
    && ref($binding) eq 'HASH' && $version->($binding->{schemaVersion}, 5)
    && ref($receipt) eq 'HASH' && $version->($receipt->{schemaVersion}, 7)
    && ref($ir) eq 'HASH' && ref($ir->{types}) eq 'ARRAY' && ref($ir->{declarations}) eq 'ARRAY';
  $fail->('inconsistent independent witnesses') unless $same->($binding->{owned}, $owned)
    && $same->($model->{bindingIr}, $ir)
    && $digest->($model->{bindingIrSha256})
    && $owned->{bindingIrSha256} eq $model->{bindingIrSha256}
    && $receipt->{bindingIrSha256} eq $model->{bindingIrSha256}
    && $receipt->{modelSha256} eq sha256_hex(read_bytes('model.json'))
    && $model->{profile} eq 'native-library-v1' && $receipt->{profile} eq 'native-library-v1'
    && $binding->{profile} eq 'native-library-v1' && $binding->{backend} eq 'perl'
    && $version->($model->{pointerBits}, 64) && $model->{byteOrder} eq 'little'
    && $digest->($manifest->{runtimeIdentity}) && $digest->($manifest->{nativeRuntimeIdentity})
    && $binding->{runtimeIdentity} eq $manifest->{runtimeIdentity}
    && $receipt->{runtimeIdentity} eq $manifest->{nativeRuntimeIdentity};
  my $relative = $manifest->{module}; $relative =~ s{::}{/}g;
  $fail->('invalid public module or native identities') unless $binding->{publicModule} eq "lib/$relative.pm"
    && defined($owned->{prefix}) && $owned->{prefix} =~ /\A[A-Za-z_][A-Za-z0-9_]*\z/
    && $owned->{gmpLibrary} eq 'libgmp-lean-bridge.so.10'
    && defined($owned->{componentLibrary}) && $owned->{componentLibrary} =~ /\Alibcomponent_[0-9a-f]{20}\.so\z/
    && $owned->{componentLibrary} eq $receipt->{library}
    && $digest->($owned->{publicHeaderSha256}) && $digest->($owned->{publicSourceSha256});
  $fail->('public C identities differ from the inventory') unless ref($manifest->{files}) eq 'HASH'
    && defined($manifest->{files}{"owned/include/$owned->{prefix}.h"})
    && $manifest->{files}{"owned/include/$owned->{prefix}.h"} eq $owned->{publicHeaderSha256}
    && defined($manifest->{files}{"owned/src/$owned->{prefix}.c"})
    && $manifest->{files}{"owned/src/$owned->{prefix}.c"} eq $owned->{publicSourceSha256};
  my $parameter = sub {
    my ($parameters, $anchor) = @_;
    $fail->('invalid parameter anchor') unless ref($parameters) eq 'ARRAY' && defined($anchor) && !ref($anchor);
    my @matches = grep { defined($parameters->[$_]{name}) && $parameters->[$_]{name} eq $anchor } 0..$#$parameters;
    $fail->('ambiguous parameter anchor') unless @matches == 1;
    return $matches[0];
  };
  my @signatures;
  for my $type (sort { $a->{id} cmp $b->{id} } @{$ir->{types}}) {
    next unless $type->{kind} eq 'callback' && $type->{callable}{result}{ownership} eq 'borrow';
    my $result = $type->{callable}{result};
    $fail->('non-local callback anchor') unless $result->{lifetime}{scope} eq 'parameter';
    my $index = $parameter->($type->{callable}{parameters}, $result->{lifetime}{anchor});
    $fail->('invalid callback owner parameter') unless $type->{callable}{parameters}[$index]{ownership} eq 'borrow';
    push @signatures, {id => $type->{id}, parameter => $index};
  }
  $fail->('missing callback signatures') unless @signatures;
  my $callbacks = {schemaVersion => 1, ownership => 'borrow', lifetime => 'parameter',
    anchor => 'original-argument-owner', expiration => 'owner-release-or-transfer',
    descendants => 'transitive', validation => 'generation-and-owner-tree',
    independentOwnership => 'explicit-retain-or-copy', maximumDepth => 128,
    hostResultHandoff => 'before-callback-frame-expires', signatures => \@signatures};
  $fail->('callback owners differ from native signatures') unless $same->($graph->{callbackResultAnchors}, $callbacks)
    && $same->($receipt->{callbackResultAnchors}, $callbacks);
  my %public_callbacks = (%$callbacks, arguments => 'whole-values', results => 'checked-whole-values',
    emptyValues => 'owner-scoped', independentRetains => 'preserved', identityEquality => 'native-identity',
    parameterNumbering => 'callback-local', hostReply => 'value-or-whole-owner',
    hostArguments => 'borrowed-raw-values', nativeClosures => 'identity-preserved',
    independentOwnership => 'retain-or-copy_value');
  $fail->('callback owners differ from the public policy') unless $same->($owned->{callbackResultAnchors}, \%public_callbacks);

  my (@moves, @anchors, @receivers);
  for my $fn (@{$ir->{declarations}}) {
    my $receiver = defined($fn->{receiver});
    my @parameters = ($receiver ? ($fn->{receiver}) : (), @{$fn->{parameters}});
    my @moving = grep { $parameters[$_]{ownership} eq 'transfer' } 0..$#parameters;
    push @moves, {bindingId => $fn->{id}, parameters => \@moving} if @moving;
    push @receivers, {bindingId => $fn->{id}, kind => $fn->{kind}, owner => $fn->{owner}, argument => 0} if $receiver;
    next unless $fn->{result}{ownership} eq 'borrow';
    my $lifetime = $fn->{result}{lifetime};
    if ($lifetime->{scope} eq 'receiver') {
      $fail->('missing receiver result anchor') unless $receiver && $lifetime->{anchor} eq 'receiver';
      push @anchors, {bindingId => $fn->{id}, receiver => JSON::PP::true};
    } else {
      $fail->('invalid result anchor scope') unless $lifetime->{scope} eq 'parameter';
      push @anchors, {bindingId => $fn->{id}, parameter => $parameter->($fn->{parameters}, $lifetime->{anchor})};
    }
  }
  my %native;
  $native{inputTransfers} = {schemaVersion => 1, ownership => 'whole-result-owner',
    validation => 'before-consumption', consumption => 'before-lean-call',
    failure => 'consumed-after-handoff', viewLifetime => 'until-call-returns', exports => \@moves} if @moves;
  $native{resultAnchors} = {schemaVersion => @receivers ? 2 : 1, ownership => 'borrow',
    lifetime => @receivers ? 'receiver-or-parameter' : 'parameter', anchor => 'original-result-owner',
    expiration => 'owner-release-or-transfer', descendants => 'transitive', validation => 'generation-and-owner-tree',
    independentOwnership => 'explicit-retain-or-copy', maximumDepth => 128, exports => \@anchors} if @anchors;
  $native{receiverExports} = {schemaVersion => 1, callingConvention => 'receiver-first', exports => \@receivers} if @receivers;
  my %extensions = (
    inputTransfers => {arguments => 'whole-values', aliases => 'shared-owner', borrowedInputs => 'reject', independentRetains => 'preserved'},
    resultAnchors => {arguments => 'whole-values', results => 'checked-whole-values', emptyValues => 'owner-scoped',
      independentRetains => 'preserved', identityEquality => 'native-identity'},
    receiverExports => {values => 'checked-whole-result', members => 'snake-case', properties => 'read-only-zero-argument-methods',
      owners => 'nominal-whole-values', consumingReceivers => 'original-owner-handoff'}
  );
  for my $name (qw(inputTransfers resultAnchors receiverExports)) {
    if (exists $native{$name}) {
      my %expected = (%{$native{$name}}, %{$extensions{$name}});
      $fail->("inconsistent $name capability") unless $same->($graph->{$name}, $native{$name})
        && $same->($receipt->{$name}, $native{$name}) && $same->($owned->{$name}, \%expected);
    } else {
      $fail->("invented $name capability") if exists($graph->{$name}) || exists($receipt->{$name}) || exists($owned->{$name});
    }
  }
  $exact->($owned, qw(schemaVersion prefix gmpLibrary componentLibrary bindingIrSha256
    publicHeaderSha256 publicSourceSha256 callbackResultAnchors), keys %native);
  if (exists $graph->{hostCallbacks}) {
    my $host = $graph->{hostCallbacks};
    $fail->('invalid host callback capability') unless ref($host) eq 'HASH' && $version->($host->{schemaVersion}, 1)
      && $host->{lifetime} eq 'call' && $host->{recovery} eq 'typed-value-v1'
      && $digest->($host->{trampolineSha256}) && ref($host->{signatures}) eq 'ARRAY' && @{$host->{signatures}}
      && $receipt->{callbackSourceSha256} eq $host->{trampolineSha256}
      && exists($manifest->{files}{'callbacks.c'}) && $manifest->{files}{'callbacks.c'} eq $host->{trampolineSha256};
  } else {
    $fail->('unexpected host callback source') if exists($receipt->{callbackSourceSha256}) || exists($manifest->{files}{'callbacks.c'});
  }
  return $owned;
}
1;

